"""Approved affiliate links, server-cookie attribution and verified commission reads."""
def extend(spec):
 from authorization import object_schema,operation,parameter,REF,UUID
 s=spec['components']['schemas'];paths=spec['paths']
 s['AffiliateStatus']=object_schema({'state':{'type':'string','enum':['NONE','ACTIVE','SUSPENDED']}})
 s['AffiliateProductLink']=object_schema({'code':{'type':'string','pattern':'^[a-f0-9]{32}$'},'productId':UUID,'path':{'type':'string','pattern':'^/api/v1/affiliate-links/[a-f0-9]{32}$'}})
 current=operation('API-222','Current CUSTOMER and persisted affiliate membership/entitlement status. No staff role or business pricing is granted.','AffiliateStatus',[])
 create=operation('API-223','Current CUSTOMER with exactly one ACTIVE AFFILIATE_MARKETING entitlement; CSRF/Idempotency-Key required. Stable random link per applicant/product, eligible active NG product only. Atomic audit; replay rechecks current access. No bank or financial side effect.','AffiliateProductLink',[parameter('id','path',UUID,True),parameter('X-CSRF-TOKEN','header',{'type':'string','minLength':43,'maxLength':43},True),parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True)])
 for op in (current,create):op['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}}
 paths['/api/v1/me/affiliate']={'get':current};paths['/api/v1/me/affiliate/links/{id}']={'put':create}
 money={'type':'string','pattern':r'^\d+\.\d{2}$'}
 s['AffiliateEarning']=object_schema({'orderId':UUID,'orderNumber':{'type':'string','maxLength':40},'earned':money,'reversed':money,'net':money,'state':{'type':'string','enum':['PENDING','AVAILABLE','HELD','REVERSED']},'availableAt':{'type':['string','null'],'format':'date-time'}})
 s['AffiliateEarnings']=object_schema({'currency':{'const':'NGN'},'pending':money,'available':money,'held':money,'reversed':money,'items':{'type':'array','maxItems':20,'items':REF('AffiliateEarning')},'page':{'type':'integer','minimum':0,'maximum':10000},'size':{'const':20},'totalElements':{'type':'integer','minimum':0},'totalPages':{'type':'integer','minimum':0}})
 earnings=operation('API-225','Current CUSTOMER with ACTIVE or SUSPENDED affiliate access, own party only. Verified retail payment earns frozen 5 percent merchandise net of discounts, excluding tax/shipping. Append-only cumulative refund reversals. Availability requires completed delivery plus seven days; unresolved refunds/operational holds block availability. No payouts or buyer PII. Unknown/repeated parameters and bodies rejected. No retroactive earnings without a frozen commission policy.','AffiliateEarnings',[parameter('page','query',{'type':'integer','minimum':0,'maximum':10000,'default':0})])
 earnings['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}}}
 paths['/api/v1/me/affiliate/earnings']={'get':earnings}
 paths['/api/v1/affiliate-links/{code}']={'get':{'operationId':'API-224','description':'Public browser visit, bounded per-instance rate. Active affiliate creates/updates an anonymous random seven-day visit capability in a separate HttpOnly SameSite=Lax host cookie (Secure outside explicitly insecure local). Redirect only to the stored product UUID. Suspended links redirect without new attribution. Expired visits are removed in bounded batches; orders retain immutable snapshots. No login required or commission created. Checkout accepts only the server cookie and excludes self/expired/suspended/business attribution.','security':[],'parameters':[parameter('code','path',{'type':'string','pattern':'^[a-f0-9]{32}$'},True)],'responses':{'302':{'description':'Stored product destination','headers':{'Location':{'schema':{'type':'string','pattern':'^/products/[a-f0-9-]{36}$'}},'Cache-Control':{'schema':{'const':'no-store'}},'Set-Cookie':{'schema':{'type':'string'},'description':'Optional seven-day affiliate visit cookie; separate from BFF identity.'}}},'404':{'description':'No active product link'},'429':{'description':'Visit budget exceeded'}}}}
